set local role authenticated;
do $test$
declare c uuid:='20000000-0000-4000-8000-000000000001';e uuid:='20000000-0000-4000-8000-000000000002';s uuid:='20000000-0000-4000-8000-000000000003';ad uuid:='20000000-0000-4000-8000-000000000004';j uuid:='30000000-0000-4000-8000-000000000001';f uuid;v uuid;r jsonb;n int; denied boolean;topic text:='sphere-private-chat-'||c::text||':'||e::text;
begin
 perform set_config('request.jwt.claim.sub',c::text,true);
 insert into public.sp_messages(sender_id,receiver_id,text,job_id) values(c,e,'Synthetic hello',j);
 if (select count(*) from public.sp_messages where job_id=j)<>1 then raise exception 'chat send failed';end if;
 perform public.sp_set_show_last_seen(true);perform public.sp_seen_ping();
 perform set_config('request.jwt.claim.sub',e::text,true);
 perform public.sp_set_show_last_seen(true);perform public.sp_seen_ping();
 if not (public.sp_last_seen(c)->>'visible')::boolean or not public.sp_private_chat_topic_allowed(topic) then raise exception 'private presence denied';end if;
 denied=false;begin insert into public.sp_messages(sender_id,receiver_id,text,job_id) values(e,c,'https://example.invalid',j);exception when others then denied=true;end;if not denied then raise exception 'contact filter failed';end if;
 perform set_config('request.jwt.claim.sub',s::text,true);
 if exists(select 1 from public.sp_messages where job_id=j) or public.sp_private_chat_topic_allowed(topic) or (public.sp_last_seen(c)->>'visible')::boolean then raise exception 'stranger access';end if;
 denied=false;begin perform public.sp_admin_overview();exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'admin access leaked';end if;
 denied=false;begin perform public.sp_files_add_link(j,'preview','https://example.invalid/a.mp4','test','');exception when others then denied=true;end;if not denied then raise exception 'stranger delivery access';end if;
 perform set_config('request.jwt.claim.sub',e::text,true);
 r=public.sp_editor_offer_status();if not (r->>'is_free')::boolean then raise exception 'offer missing';end if;
 perform public.sp_submit_proof_video('https://www.youtube.com/watch?v=synthetic00');
 r=public.sp_claim_free_verification();if (r->>'ready')::boolean then raise exception 'claim without screenshot';end if;
 perform public.sp_work_request_extension(j,6,'Synthetic extension');
 perform set_config('request.jwt.claim.sub',c::text,true);
 perform public.sp_work_answer_extension(j,true);
 if (select extended_hours from public.sp_project_work where job_id=j)<>6 then raise exception 'extension failed';end if;
 perform set_config('request.jwt.claim.sub',e::text,true);
 r=public.sp_files_begin(j,'preview','test.mp4','video/mp4',100);
 f=(r->>'id')::uuid;
 denied=false;begin perform public.sp_files_finish(f,true,5,'synthetic');exception when others then denied=true;end;if not denied then raise exception 'finish without object';end if;
 perform public.sp_files_finish(f,false,null,null);
 perform public.sp_files_add_link(j,'preview','https://example.invalid/preview.mp4','Synthetic preview','');
 for n in 1..3 loop
  perform set_config('request.jwt.claim.sub',c::text,true);
  perform public.sp_rev_request(j,'Synthetic revision');
  if not exists(select 1 from public.sp_revisions where job_id=j and number=n and fee=0 and status='open') then raise exception 'free revision failed';end if;
  perform set_config('request.jwt.claim.sub',e::text,true);
  perform public.sp_files_add_link(j,'preview','https://example.invalid/preview.mp4','Synthetic preview','');
 end loop;
 perform set_config('request.jwt.claim.sub',c::text,true);
 perform public.sp_rev_request(j,'Synthetic paid revision');
 select id into v from public.sp_revisions where job_id=j and number=4 and fee=50 and status='awaiting_payment';
 if v is null then raise exception 'fourth revision not locked';end if;
 perform public.sp_rev_cancel(v);
 perform public.sp_cr_create(j,'Synthetic new requirement',0,2,null,'{}');
 select id into v from public.sp_change_requests where job_id=j;
 perform set_config('request.jwt.claim.sub',e::text,true);
 perform public.sp_cr_answer(v,true,'Synthetic accepted');
 perform public.sp_files_add_link(j,'preview','https://example.invalid/preview.mp4','Synthetic final preview','');
 select id into f from public.sp_project_files where job_id=j and kind='preview' and status='ready' order by version desc limit 1;
 denied=false;begin perform public.sp_final_submit(j,f,'https://example.invalid/clean.mp4','');exception when others then denied=true;end;if not denied then raise exception 'final before approval';end if;
 perform set_config('request.jwt.claim.sub',c::text,true);perform public.sp_approve_preview(j);
 perform set_config('request.jwt.claim.sub',e::text,true);perform public.sp_final_submit(j,f,'https://example.invalid/clean.mp4','');
 perform set_config('request.jwt.claim.sub',c::text,true);
 if (select delivery_link from public.sp_jobs where id=j) is not null then raise exception 'final exposed';end if;
 denied=false;begin perform 1 from public.sp_final_files where job_id=j;exception when insufficient_privilege then denied=true;end;if not denied then raise exception 'final table readable';end if;
 perform public.sp_dispute_open(j,'quality','Synthetic issue for testing only');
 insert into public.sp_blocks(blocker_id,blocked_id) values(c,e);
 denied=false;begin insert into public.sp_messages(sender_id,receiver_id,text,job_id) values(c,e,'Synthetic blocked',j);exception when others then denied=true;end;if not denied or public.sp_private_chat_topic_allowed(topic) then raise exception 'block enforcement failed';end if;
 perform set_config('request.jwt.claim.sub',ad::text,true);
 r=public.sp_admin_overview();if (r->>'users')::int<>4 then raise exception 'admin overview failed';end if;
 if jsonb_array_length(public.sp_admin_verifications())<>1 or jsonb_array_length(public.sp_admin_profiles('EDITOR',null))<>1 or jsonb_array_length(public.sp_admin_users(null,'all',200))<>4 then raise exception 'admin projection failed';end if;
 perform public.sp_admin_editor_review(null);perform public.sp_admin_project_metrics(array[j]);perform public.sp_admin_audit_list(10,null);
 if not exists(select 1 from public.sp_disputes where job_id=j and status='open') then raise exception 'admin dispute read failed';end if;
 if not (public.sp_admin_payments()->>'simulation_only')::boolean then raise exception 'payment isolation failed';end if;
end $test$;
select 'synthetic chat, private presence, stranger denial, proof/offer, extension, free/paid revisions, change, final lock, dispute, block, admin read and payment isolation' as suite,'PASS' as status;
